CREATE TABLE p1(one PRIMARY KEY, two); INSERT INTO p1 VALUES('d','D'),('e','E'),('f','F'); CREATE TABLE c1(a,b,FOREIGN KEY(a) REFERENCES p1 ON DELETE SET NULL); CREATE TABLE c2(a,b,FOREIGN KEY(a) REFERENCES p1 ON DELETE SET DEFAULT); CREATE TABLE c3(a,b,FOREIGN KEY(a) REFERENCES p1 ON DELETE CASCADE); CREATE TABLE c4(a,b,FOREIGN KEY(a) REFERENCES p1 ON UPDATE SET NULL); CREATE TABLE c5(a,b,FOREIGN KEY(a) REFERENCES p1 ON UPDATE SET DEFAULT); CREATE TABLE c6(a,b,FOREIGN KEY(a) REFERENCES p1 ON UPDATE CASCADE); INSERT INTO c1 VALUES(NULL,'aaa'); INSERT INTO c2 VALUES(NULL,'bbb'); INSERT INTO c4 VALUES('d','aaa'); INSERT INTO c5 VALUES('e','bbb'); INSERT INTO c6 VALUES('f','ccc');